import {REALMS,LIFE,JOBS,AREAS,EVENTS,fresh,living,realmName,power,income,act,validSave,randomName} from './game.js';
const KEY='qinglan-family-v1',esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=fresh(),tab='home',chosen=1,saveOK=true,loadWarning='';
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validSave(parsed))state=parsed;else loadWarning='旧存档格式异常，已载入新开局；旧存档暂未覆盖。';}}catch{loadWarning='无法读取本地存档，请使用导出存档保留进度。';}
const oldStarterNames=['沈长青','沈清禾','沈砚舟','沈知微'];
let migratedLegacyNames=false;
if(!state.namesRandomized&&state.members.length===4&&state.members.every((m,i)=>m.name===oldStarterNames[i])){state.members.forEach(m=>m.name=randomName());state.namesRandomized=true;migratedLegacyNames=true;loadWarning=loadWarning||'初始族人的名字已随机生成；可在「家族谱系」中随时改名。';}
let migratedBattle=false;
if(state.battle&&state.battle.locationName===undefined){const area=AREAS[state.battle.area];Object.assign(state.battle,{locationName:area?.name||'战场',enemyName:'守地妖兽',reward:area?.reward||0,herbs:area?.herbs||0});migratedBattle=true;}
const tabs=[['home','◈','山门总览'],['clan','♧','家族谱系'],['estate','▦','家族产业'],['explore','⚔','外出历练'],['guide','☷','修行典籍']];
const titles={home:['山门总览','一山烟雨，一族仙途。'],clan:['家族谱系','仙路漫漫，薪火相传。'],estate:['家族产业','积寸土之功，立百世之基。'],explore:['外出历练','山外有山，道在险途。'],guide:['修行典籍','知进退，明得失，方能长生。']};
const bar=(value,cls='')=>`<div class="bar ${cls}"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;
const fmt=n=>Math.floor(n).toLocaleString('zh-CN');
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveOK=true;}catch{saveOK=false;toast('自动存档不可用，请在「存档」中导出进度。');}}
function run(type,payload={}){try{act(state,type,payload);save();render();if(state.battle)battleModal();else if(document.querySelector('#modal').open&&document.querySelector('#modal').dataset.kind==='battle')document.querySelector('#modal').close();if(state.end)endModal();else toast(({event:state.battle?'强敌来袭，已进入战斗。':'家族决断已记入纪事。',upgrade:'产业扩建完成，已消耗本年一次决策。',recruit:'新族人已入谱。',heal:'疗伤已开始，推进一年后结算。',train:'闭关所得已记入修为。',break:'突破闭关已开始，等待岁月结算。',explore:'已踏入历练之地。',fight:'本回合战斗结束。',defend:'已转为守势。',flee:'已尝试撤退。',year:'岁月已推进，长期修行已结算。',rename:'名字已写入族谱。'})[type]||'操作完成。');return{ok:true};}catch(e){toast(e.message);return{ok:false,error:e.message};}}
function person(m,full=false){const task=m.task?`<p class="task-state">${m.task.type==='heal'?'疗伤调息':'闭关突破'}中 · 尚余 ${m.task.remaining} 年</p>`:'';return `<article class="person ${!m.alive?'departed':''}"><div class="person-head"><div class="monogram">${esc(m.name.slice(-1))}</div><div><h3>${esc(m.name)} ${m.id===state.leader?'<small class="leader">家主</small>':''}</h3><span class="muted">${realmName(m)} · ${esc(m.trait)}</span></div><span class="job-label">${m.alive?esc(m.job):'已故'}</span></div><div class="person-meta"><span>骨龄 <b>${m.age}</b> / ${LIFE[m.realm]}</span><span>资质 <b>${m.talent}</b></span></div><div class="meter-label"><span>修为</span><span>${m.xp===100?'可突破':m.xp+' / 100'}</span></div>${bar(m.xp)}${full?`<div class="meter-label"><span>气血</span><span>${m.hp} / 100 · 战力 ${power(m)}</span></div>${bar(m.hp,'health')}${task}<p class="muted">第 ${m.gen} 代${!m.alive?' · 仙历 '+m.died+' 年陨落':''}</p>${m.alive?`<label class="job-select">族务安排<select data-job="${m.id}" aria-label="${esc(m.name)}的族务" ${m.task?'disabled':''}>${JOBS.map(j=>`<option ${j===m.job?'selected':''}>${j}</option>`).join('')}</select></label><div class="person-actions"><button data-act="train" data-id="${m.id}" ${state.actions<1||m.xp===100||m.task?'disabled':''}>闭关 <small>8 灵草</small></button><button data-act="break" data-id="${m.id}" ${m.xp<100||state.actions<1||m.task?'disabled':''}>突破 <small>${m.stage===(m.realm===0?13:4)?'需 2 年':'需 1 年'}</small></button><button data-act="heal" data-id="${m.id}" ${m.hp===100||state.actions<1||m.task?'disabled':''}>疗伤 <small>需 1 年</small></button><button data-rename="${m.id}">改名</button></div>`:''}`:''}</article>`;}
function eventCard(){if(state.event===null)return `<section class="event-card settled"><span class="eyebrow">山门无事</span><h2>风止，灯火可亲。</h2><p>本年事务已了。安排族务，培养晚辈，或去山外寻找机缘。</p><button class="outline" data-tab="explore">前往历练 <span>↗</span></button></section>`;const e=EVENTS[state.event];return `<section class="event-card"><div class="section-top"><span class="eyebrow">家族事件 · 仙历 ${state.year} 年</span><span class="pill amber">待家主定夺</span></div><h2>${e.title}</h2><p>${e.text}</p><div class="choices">${e.choices.map((c,i)=>`<button class="choice" data-event="${i}" ${state.money+(c.money||0)<0||state.herbs+(c.herbs||0)<0?'disabled':''}><strong><span class="choice-number">${['壹','贰','叁'][i]}</span>${c.label}<span class="arrow">↗</span></strong><small>${c.hint}</small></button>`).join('')}</div></section>`;}
function chronicle(){return `<aside class="chronicle"><div class="section-top"><h2>家族纪事</h2><span class="muted">${state.log.length} 则</span></div><div class="timeline">${state.log.slice(0,12).map(l=>`<article class="entry ${l.type}"><span class="entry-year">仙历 ${l.year} 年</span><p>${esc(l.text)}</p></article>`).join('')}</div><div class="chronicle-footer">凡所经历，皆为传承。</div></aside>`;}
function home(){const clan=living(state),leader=clan.find(m=>m.id===state.leader);return `<section class="mountain-banner"><div class="banner-content"><span class="eyebrow">云泽郡 · 青岚山</span><h2>青岚沈氏</h2><p>立族于微末，问道于天地。</p><div class="banner-pills"><span>家主 ${esc(leader?.name||'虚位')}</span><span>${state.rep<80?'初立山门':state.rep<200?'一方世家':'名门望族'}</span></div></div><span class="vertical-poem">山河有尽 · 仙途无涯</span><span class="image-credit">青岚山 · 山门</span></section><div class="main-columns"><div>${eventCard()}<section class="clan-preview"><div class="section-top"><h2>族中修士 <small>${clan.length} 人</small></h2><button class="text-btn" data-tab="clan">查看族谱 ↗</button></div><div class="people-grid">${clan.slice(0,4).map(m=>person(m)).join('')}</div></section></div>${chronicle()}</div>`;}
function clanPage(){return `<div class="page-intro"><p>修行者每年增长骨龄。耗尽寿元即坐化，突破大境界可延长寿元。</p><button class="primary" data-act="recruit" ${state.actions<1?'disabled':''}>招纳旁支 <small>100 灵石 · 1 次决策</small></button></div><div class="people-grid full">${living(state).map(m=>person(m,true)).join('')}</div>${state.members.some(m=>!m.alive)?`<div class="section-top ancestors-title"><h2>祖祠 · 先人录</h2></div><div class="people-grid full">${state.members.filter(m=>!m.alive).reverse().map(m=>person(m,true)).join('')}</div>`:''}`;}
const buildings=[['field','灵田','田','每级每年产出 28 灵石、7 灵草。安排族人照料，每人另产 9 灵草。'],['market','云泽坊市','市','每级每年收入 40 灵石。安排族人经商，每人另得 30 灵石。'],['hall','传功堂','道','每级增加修炼族人年度修为 3 点，大境界突破率提高 1.5%。每级年耗 6 灵石。'],['ward','护山大阵','阵','每级增加 40 点山门防御。守山族人以自身战力协防。每级年耗 6 灵石。']];
function estatePage(){const i=income(state);return `<div class="balance panel"><div><span class="muted">预计年度净收益</span><strong class="${i.earn-i.upkeep>=0?'jade':'danger'}">${i.earn-i.upkeep>=0?'+':''}${i.earn-i.upkeep} <small>灵石</small></strong></div><p>年收入 ${i.earn} · 年供奉 ${i.upkeep} · 灵草 +${i.herbs}<br>族人每人每年需要 16 灵石供奉。连续三年亏空，家族覆灭。</p></div><div class="building-grid">${buildings.map(([key,title,seal,desc])=>`<article class="building panel"><span class="building-seal">${seal}</span><span class="pill">${state.buildings[key]} 级 / 10 级</span><h2>${title}</h2><p>${desc}</p><button class="outline" data-upgrade="${key}" ${state.buildings[key]===10||state.actions<1?'disabled':''}>${state.buildings[key]===10?'已达上限':`扩建 · ${state.buildings[key]*100} 灵石`} <span>＋</span></button></article>`).join('')}</div><section class="panel relations"><h2>周边势力</h2><div class="relation-row"><span>临川陆家</span><span>关系 ${state.relation} / 100</span><strong>${state.relation<30?'交恶':state.relation>65?'友善':'观望'}</strong></div><p>议事堂中的抉择会改变双方关系与外患。外患超过 45 时，每年有概率遭到袭击。</p></section>`;}
function explorePage(){const clan=living(state);if(!clan.some(m=>m.id===chosen))chosen=clan[0]?.id;const m=clan.find(x=>x.id===chosen);return `<div class="expedition-banner"><span class="eyebrow">云泽山海</span><h2>去山外，觅一线机缘。</h2><p>出发消耗一次决策。战斗中可进攻、防御或撤退，气血归零将永久陨落。</p></div><div class="explore-picker"><label for="explorer">派遣族人</label><select id="explorer">${clan.map(x=>`<option value="${x.id}" ${x.id===chosen?'selected':''}>${esc(x.name)} · ${realmName(x)} · 战力 ${power(x)} · 气血 ${x.hp}</option>`).join('')}</select>${state.battle?'<button class="primary" data-battle>继续战斗</button>':''}</div><div class="area-grid">${AREAS.map((a,i)=>{const locked=!m||m.realm<a.level;return `<article class="area panel"><div class="area-index">0${i+1}</div><span class="eyebrow">${a.tag} · ${REALMS[a.level]}起</span><h2>${a.name}</h2><p>${a.desc}</p><div class="area-info"><span>妖兽战力约 ${a.power}</span><span class="${m&&power(m)>=a.power?'jade':'danger'}">${locked?'境界未至':power(m)>=a.power?'可从容应对':'凶险，谨慎前往'}</span></div><div class="loot">战胜所得 <strong>${a.reward}</strong> 灵石 · <strong>${a.herbs}</strong> 灵草</div><button class="${i===0?'primary':'outline'}" data-explore="${i}" ${locked||state.actions<1||!!state.battle||m?.hp<40?'disabled':''}>${locked?'尚未解锁':'进入'+a.name}<span>${locked?'◇':'↗'}</span></button></article>`;}).join('')}</div>`;}
function guidePage(){return `<section class="panel guide"><span class="eyebrow">入道须知</span><h2>先活下来，再问长生。</h2><ol><li>在山门处理事件，每个选择会直接影响资源、族心或外患。强敌事件中选择应战，会直接进入战斗。</li><li>在族谱安排族务；闭关、疗伤、突破、招纳、扩建、出行各耗一次决策，每年共三次。分配族务与处理事件不耗决策。</li><li>疗伤需一年；普通突破闭关一年，大境界突破闭关两年。开始后不会立刻结算，推进年份才会显示结果。</li><li>修为达到 100 后，手动突破。小层次成功率 95%；大境界成功率由资质与传功堂决定，最高 88%。大境界突破失败后，有 10% 概率直接陨落。</li><li>推进一年，结算产业和供奉、长期修行、修为与寿元。每五年，在至少两名修士存活且未达 16 人时，一名族中晚辈成年入道。</li><li>历练需逐回合决策；守势降低伤害，撤退成功率 78%。气血越低，战力越低，切莫恋战。</li><li>族人尽殁、族心降至零或连续三年亏空，均会导致家族覆灭。大乘圆满渡劫成功，即达成飞升结局。</li></ol><h2>修炼境界</h2><div class="realm-road">${REALMS.map((r,i)=>`<div><span class="realm-n">${String(i+1).padStart(2,'0')}</span><h3>${r}</h3><p>${i===0?'一至十三层':'初期 · 中期 · 后期 · 圆满'}</p><small>游戏寿元上限 ${fmt(LIFE[i])} 岁</small></div>`).join('')}</div><p class="muted">境界名称参考《凡人修仙传》；寿元、成长速度与成功率为本作游戏数值。世界、角色与事件均为原创。<a href="https://zh.wikipedia.org/wiki/%E5%87%A1%E4%BA%BA%E4%BF%AE%E4%BB%99%E4%B9%8B%E4%BB%99%E7%95%8C%E7%AF%87" target="_blank" rel="noreferrer">境界参考 ↗</a></p><h2>关于存档</h2><p>每次操作会自动保存到当前浏览器。换设备或清理浏览器前，请先导出存档。此版本为单机游戏，存档不会自动同步到其他设备。</p></section>`;}
function render(){const flow=income(state);document.querySelector('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home" aria-label="青岚世家山门总览"><span class="brand-seal">青</span><div><strong>青岚世家</strong><small>家 族 修 仙 录</small></div></a><div class="sidebar-rule"></div><span class="nav-label">山门诸事</span><nav>${tabs.map(([id,icon,name])=>`<button data-tab="${id}" class="nav-item ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}${id==='home'&&state.event!==null?'<span class="nav-badge">1</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="clan-condition"><span>家族气象</span><strong>${state.end?'此世终章':state.morale<30?'风雨飘摇':state.threat>60?'暗流涌动':'百废待兴'}</strong></div><div class="condition-line"><span>族心</span><span>${state.morale} / 100</span></div>${bar(state.morale)}<div class="condition-line"><span>外患</span><span class="${state.threat>45?'danger':''}">${state.threat} / 100</span></div>${bar(state.threat,'risk')}<button class="save-button" data-save>▣ <span>存档与传承</span></button><small class="save-state">${saveOK?'进度保存在当前浏览器':'自动存档不可用，请导出'}</small></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumb">青岚山 <span>/</span> ${titles[tab][0]}</div><div class="top-actions"><span class="season">◇ 山中岁月</span><button class="top-save" data-save>存档</button><button class="icon-button" data-tab="guide" aria-label="玩法说明">?</button></div></header><div class="content"><div class="page-heading"><div><h1>${titles[tab][0]}</h1><p>${titles[tab][1]}</p></div><div class="year-control"><div><strong>仙历 ${state.year} 年</strong><span>本年决策 ${state.actions} / 3</span></div><button class="primary year-button" data-act="year" ${state.end||state.battle||state.event!==null?'disabled title="请先处理当前家族事件"':''}>推进一年 <span>→</span></button></div></div>${state.event!==null?'<p class="pending-hint">当前有家族事件待决，请在下方选择一项处理。</p>':''}${state.end?`<div class="end-banner">${esc(state.end)} <button data-save>开启新一世</button></div>`:''}<section class="resources" aria-label="家族资源"><div><span class="resource-icon">◈</span><div><span>族库灵石</span><strong>${fmt(state.money)}<small class="${flow.earn-flow.upkeep>=0?'jade':'danger'}">${flow.earn-flow.upkeep>=0?'+':''}${flow.earn-flow.upkeep} / 年</small></strong></div></div><div><span class="resource-icon">♧</span><div><span>灵草储备</span><strong>${fmt(state.herbs)}<small>+${flow.herbs} / 年</small></strong></div></div><div><span class="resource-icon">♙</span><div><span>在世修士</span><strong>${living(state).length}<small>人 / 16 人</small></strong></div></div><div><span class="resource-icon">✧</span><div><span>家族声望</span><strong>${fmt(state.rep)}<small>${state.rep<80?'籍籍无名':state.rep<200?'声名渐起':'名动一方'}</small></strong></div></div></section><div class="mobile-condition"><span>族心 ${state.morale} / 100</span><span>外患 ${state.threat} / 100</span><span>${state.debt?"连续亏空 "+state.debt+" 年":"家族收支正常"}</span></div><div class="view">${({home,clan:clanPage,estate:estatePage,explore:explorePage,guide:guidePage})[tab]()}</div><footer class="page-footer"><span>青岚世家 · 单机试玩版</span><span>一念兴衰，百世传承。</span></footer></div></main>`;}
function modal(html,kind){const d=document.querySelector('#modal');d.dataset.kind=kind;d.innerHTML=`<button class="modal-close" data-close aria-label="关闭">×</button>${html}`;if(!d.open)d.showModal();}
function battleModal(){const b=state.battle;if(!b)return;const m=state.members.find(x=>x.id===b.member);modal(`<span class="eyebrow">${esc(b.locationName||'战场')} · 第 ${b.turn} 回合</span><h2>狭路相逢</h2><div class="combatants"><div><h3>${esc(m.name)}</h3><p>${realmName(m)} · 战力 ${power(m)}</p>${bar(m.hp,'health')}<small>气血 ${m.hp} / 100</small></div><span class="versus">战</span><div><h3>${esc(b.enemyName||'强敌')}</h3><p>战力 ${b.enemy}</p>${bar(b.hp/b.max*100,'risk')}<small>气血 ${b.hp} / ${b.max}</small></div></div><div class="battle-log" aria-live="polite">${b.log.slice(-5).map(l=>`<p>${esc(l)}</p>`).join('')}</div><div class="combat-buttons"><button class="primary" data-act="fight">施展剑诀</button><button class="outline" data-act="defend">守势反击</button><button class="outline" data-act="flee">尝试撤退</button></div><p class="muted">守势降低本回合输出与受到的伤害。撤退有 22% 概率失败。</p>`,'battle');}
function endModal(){modal(`<span class="eyebrow">此世终章</span><h2>${state.end.includes('飞升')?'举霞飞升':'青山依旧在'}</h2><p>${esc(state.end)}</p><button class="primary" data-save>查看存档与传承</button>`,'end');}
function renameModal(id){const m=living(state).find(x=>x.id===id);if(!m)return;modal(`<span class="eyebrow">修订族谱</span><h2>为 ${esc(m.name)} 改名</h2><p>可使用 2 至 8 个汉字；名字会随存档保存。</p><label class="name-label" for="rename-input">族人名字</label><input id="rename-input" class="name-input" maxlength="8" value="${esc(m.name)}" autocomplete="off"><div class="save-options"><button class="outline" data-close>取消</button><button class="primary" id="confirm-rename">写入族谱</button></div>`,'rename');const input=document.querySelector('#rename-input');document.querySelector('#confirm-rename').onclick=()=>{const result=run('rename',{id,name:input.value});if(result.ok)document.querySelector('#modal').close();};input.focus();input.select();}
function saveModal(){modal(`<span class="eyebrow">存档与传承</span><h2>留一卷家书，续来日仙途。</h2><p>仙历 ${state.year} 年 · ${living(state).length} 名修士 · ${fmt(state.money)} 灵石</p><p class="muted">自动保存在当前浏览器。换设备时，可导出并导入这份存档。</p><div class="save-options"><button class="primary" data-export>导出存档</button><button class="outline" data-import>导入存档</button></div><hr><button class="danger-button" data-reset-prompt>开启新一世</button><p class="muted">新一世会替换当前进度，建议先导出存档。</p>`,'save');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b||b.disabled)return;if(b.matches('a.brand')){e.preventDefault();tab='home';render();}if(b.dataset.tab){tab=b.dataset.tab;render();}if(b.dataset.act)run(b.dataset.act,{id:Number(b.dataset.id)});if(b.dataset.event!==undefined)run('event',{index:Number(b.dataset.event)});if(b.dataset.upgrade)run('upgrade',{key:b.dataset.upgrade});if(b.dataset.explore!==undefined)run('explore',{id:chosen,area:Number(b.dataset.explore)});if(b.dataset.rename)renameModal(Number(b.dataset.rename));if(b.hasAttribute('data-battle'))battleModal();if(b.hasAttribute('data-save'))saveModal();if(b.hasAttribute('data-close'))document.querySelector('#modal').close();if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`青岚沈氏-仙历${state.year}年.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('存档已导出。');}if(b.hasAttribute('data-import'))document.querySelector('#import-file').click();if(b.hasAttribute('data-reset-prompt'))modal('<h2>确定开启新一世？</h2><p>当前进度将被替换。此操作无法撤销，已导出的存档仍可恢复。</p><div class="save-options"><button class="outline" data-save>保留此世</button><button class="danger-button" data-reset>确认重新开始</button></div>','reset');if(b.hasAttribute('data-reset')){state=fresh();tab='home';chosen=1;save();render();document.querySelector('#modal').close();toast('青岚山门重开。');}});
document.addEventListener('change',e=>{if(e.target.dataset.job)run('job',{id:Number(e.target.dataset.job),job:e.target.value});if(e.target.id==='explorer'){chosen=Number(e.target.value);render();}});
document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('存档文件过大。');const parsed=JSON.parse(await file.text());if(!validSave(parsed))throw Error('不是有效的青岚世家存档，当前进度未改变。');pendingImport=parsed;modal(`<h2>载入仙历 ${parsed.year} 年的存档？</h2><p>这会替换当前进度。请确认已保存需要保留的家族。</p><div class="save-options"><button class="outline" data-save>取消</button><button class="primary" id="confirm-import">确认载入</button></div>`,'import');document.querySelector('#confirm-import').onclick=()=>{state=pendingImport;pendingImport=null;tab='home';save();render();document.querySelector('#modal').close();toast('存档载入成功。');};}catch(err){toast(err.message||'读取存档失败。');}finally{e.target.value='';}});
let pendingImport=null;if(migratedLegacyNames||migratedBattle)save();render();if(loadWarning)toast(loadWarning);
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_clan_state',title:'查看家族状态',description:'读取当前家族年份、资源、族人以及待处理事件，不推进时间。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('不接受参数。');return structuredClone({year:state.year,actions:state.actions,money:state.money,herbs:state.herbs,morale:state.morale,members:living(state),event:state.event===null?null:EVENTS[state.event],end:state.end});}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
